49:     spawnTimer-=dt;if(spawnTimer<=0){spawnPulse();spawnTimer=Math.max(.31,1.18-time*.009)*rand(.72,1.25)}shardTimer-=dt;if(shardTimer<=0&&shards.length<3){spawnShard();shardTimer=rand(2,3.8)}
50:     for(const p of pulses){p.x+=p.vx*dt;p.y+=p.vy*dt;p.rot+=dt*3;if(collide(player,p,invuln>0?0:1))hit()}
51:     pulses=pulses.filter(p=>p.x>-70&&p.x<W+70&&p.y>-70&&p.y<H+70);
